effect.shader:
// O `rand` do AM, letra por letra.
float rand(vec2 co)
{
    float a = 719.310;
    float b = 178.233;
    float c = 33758.5453;
    float dt= dot(co.xy ,vec2(a,b));
    float sn= mod(dt,3.14);
    return fract(sin(sn) * c);
}

// Ver `am-block-dissolve.xml`.
vec2 naTela(vec2 uv) {
    vec2 t = acEntradaDePe == 1 ? uv : acTela(uv);
    return vec2(t.x, 1.0 - t.y);
}

void main() {
    vec4 texColor = texture(inputImg, acScreenNorm);   // alfa reto
    vec2 acScreenSize = acTamanhoDaTela;
    vec2 acLayerCenter = acCentroDaCamadaPx;
    vec2 acLayerSize = acTamanhoDaCamada;

    vec2 st = floor((naTela(acScreenNorm)*acScreenSize)-acLayerCenter)/acLayerSize;
    float t = seed*3197.3791;
    t = mod(t,2.8)+2.7;
    float tileSize = min(acLayerSize.x, acLayerSize.y)/size;
    st.x *= acLayerSize.x/acLayerSize.y;
    st -= offset/1000.0;
    st *= tileSize;
    if( stretch < 0.0 ) {
        st.x /= 1.0-stretch;
    } else {
        st.y /= 1.0+stretch;
    }
    st = floor(st);

    float r = rand( st*t );
    float adjFade = max(fade,0.00001);
    float adjAmount = amount;
    adjAmount -= 0.5;
    adjAmount *= 1.0+(adjFade*2.0);
    adjAmount += 0.5;
    r = smoothstep(adjAmount-adjFade, adjAmount+adjFade, r);

    fragColor = vec4(texColor.rgb, texColor.a * r);
}
